"""Engine locator for the fastText reproduction.

The paper's system IS the authors' C++ fastText supervised trainer
(https://github.com/facebookresearch/fastText, cloned in repo/).  This module
finds a usable copy of that exact trainer and forwards every hyperparameter
verbatim -- no author code is modified or re-implemented.

Order of preference:
  1. an already importable `fasttext` module,
  2. `pip install fasttext-wheel` (prebuilt wheel of the same 0.9.2 C++ sources),
  3. a native build of repo/ (`make`, or `pip install .`) when a POSIX
     toolchain is present,
  4. the authors' own PyTorch EmbeddingBag example
     (repo/python/doc/examples/FastTextEmbeddingBag.py) -- a re-implementation,
     which downgrades the verdict to "partially_reproduced".
"""

import importlib
import os
import shutil
import subprocess
import sys

import config

ENGINE = None
ENGINE_KIND = None
ENGINE_DETAIL = {}


def _record(kind, **detail):
    global ENGINE, ENGINE_KIND, ENGINE_DETAIL
    ENGINE_KIND = kind
    ENGINE_DETAIL = detail
    return ENGINE


def _try_import():
    try:
        return importlib.import_module("fasttext")
    except Exception:
        return None


def _try_pip_wheel():
    try:
        subprocess.run(
            [sys.executable, "-m", "pip", "install", "fasttext-wheel"],
            check=True, capture_output=True, timeout=600,
        )
    except Exception as exc:
        print("[engine] pip install fasttext-wheel failed: %r" % (exc,))
        return None
    return _try_import()


def _try_native_build():
    """Build the authors' C++ trainer from repo/ and import it via `pip install .`."""
    if not os.path.isdir(config.REPO_DIR):
        return None
    has_make = shutil.which("make") and (shutil.which("g++") or shutil.which("clang++"))
    if has_make:
        try:
            subprocess.run(["make"], cwd=config.REPO_DIR, check=True,
                           capture_output=True, timeout=1800)
            exe = os.path.join(config.REPO_DIR, "fasttext")
            if os.path.exists(exe):
                return _record("native-cli", binary=exe)
        except Exception as exc:
            print("[engine] native make failed: %r" % (exc,))
    try:
        subprocess.run([sys.executable, "-m", "pip", "install", config.REPO_DIR],
                       check=True, capture_output=True, timeout=1800)
    except Exception as exc:
        print("[engine] pip install repo/ failed: %r" % (exc,))
        return None
    return _try_import()


def get_engine():
    """Return (engine, kind, detail)."""
    global ENGINE
    if ENGINE is not None:
        return ENGINE, ENGINE_KIND, ENGINE_DETAIL

    ft = _try_import()
    if ft is not None:
        return _record("python-module", module=getattr(ft, "__file__", "?")), "python-module", ENGINE_DETAIL

    ft = _try_pip_wheel()
    if ft is not None:
        return _record("fasttext-wheel", module=getattr(ft, "__file__", "?")), "fasttext-wheel", ENGINE_DETAIL

    ft = _try_native_build()
    if ft is not None:
        return ft, ENGINE_KIND, ENGINE_DETAIL

    raise RuntimeError(
        "No fastText engine available: `import fasttext` failed, `pip install "
        "fasttext-wheel` failed and no POSIX toolchain was found for a native build."
    )


def train(input_path, output_path, **kwargs):
    """Train with the authors' supervised trainer; returns the model object."""
    ft, kind, _ = get_engine()
    if kind == "native-cli":
        args = ["supervised", "-input", input_path, "-output", output_path]
        for k, v in kwargs.items():
            args += ["-%s" % k, str(v)]
        subprocess.run([ENGINE_DETAIL["binary"]] + args, check=True)
        return ft.load_model(output_path + ".bin")
    return ft.train_supervised(input=input_path, output=output_path, **kwargs)


def test(model, path, k=1):
    """Evaluate on `path`; returns (N, precision@1, recall@1)."""
    if hasattr(model, "test"):
        return model.test(path, k)
    raise RuntimeError("engine has no test()")


def model_name(model):
    return getattr(model, "f", None).getName() if hasattr(model, "f") else "?"

